function balances(i){return(Array.isArray(i?.stockBalances)?i.stockBalances:[]).filter(b=>Number(b.qty||0)>0).map(b=>({...b,qty:Number(b.qty||0),locationType:b.locationType||'',locationId:b.locationId||'',locationName:b.locationName||b.location||'Unknown',status:b.status||'Not Available'}));}
function qty(i){return balances(i).reduce((a,b)=>a+b.qty,0);}function liveQty(i){return balances(i).filter(b=>!EXIT_STATUS.includes(b.status)&&b.status!=='Inactive').reduce((a,b)=>a+b.qty,0);}function avail(i){return balances(i).filter(b=>b.status==='Available').reduce((a,b)=>a+b.qty,0);}function status(i){return[...new Set(balances(i).map(b=>b.status))].join(' / ')||i.status||'';}function distribution(i){return balances(i).map(b=>`${b.locationName}: ${b.qty} (${b.status})`).join(' · ');}function ownership(i){return i.ownershipType==='third_party'?'Third-Party / R2R':'Owned';}
async function load(){return loadOverviewSummary();}
function summaryConsistent(distribution={}){if(!distribution.ownedPositions)return false;for(const w of Object.values(distribution.warehouses||{})){const available=Number(w?.availableQty||0),descriptions=Object.values(w?.availableDescriptions||{}).reduce((n,q)=>n+Number(q||0),0);if(Math.abs(available-descriptions)>0.000001)return false;}return true;}
async function loadOverviewSummary(){const[g,d,c]=await Promise.all([getDoc(SUMMARY_GLOBAL),getDoc(SUMMARY_DISTRIBUTION),getDoc(SUMMARY_CATEGORIES)]);if(!g.exists()||!d.exists()||!c.exists()||g.data().summaryVersion!==SUMMARY_VERSION||d.data().summaryVersion!==SUMMARY_VERSION||c.data().summaryVersion!==SUMMARY_VERSION||!summaryConsistent(d.data())){overviewSummary=null;return false;}overviewSummary={global:g.data(),distribution:d.data(),categories:c.data()};return true;}

function setHead(){if($('pageTitle'))$('pageTitle').textContent='Stock Inventory';if($('pageSubtitle'))$('pageSubtitle').textContent='Live stock distribution, ownership and operational status at a glance.';document.querySelectorAll('.navBtn').forEach(b=>b.className=`navBtn text-left px-3 py-2.5 rounded-xl text-xs font-semibold ${b.dataset.tab==='stock'?'bg-red-600 text-white':'bg-slate-800/50 hover:bg-slate-800'}`);}
function tabs(){return`<div class="flex flex-wrap gap-2 mb-4"><button id="stockOverview" class="px-4 py-2 rounded-lg text-xs font-bold ${view==='overview'?'bg-red-600':'bg-slate-800'}">Overview</button><button id="stockDirectory" class="px-4 py-2 rounded-lg text-xs font-bold ${view==='directory'?'bg-red-600':'bg-slate-800'}">Item Directory</button><button id="stockInactive" class="px-4 py-2 rounded-lg text-xs font-bold ${view==='inactive'?'bg-red-600':'bg-slate-800'}">Inactive</button>${can('inventory.edit')?`<button id="stockBulk" class="px-4 py-2 rounded-lg text-xs font-bold ${view==='bulk'?'bg-red-600':'bg-slate-800'}">Bulk Edit</button>`:''}</div>`;}
function bindTabs(){if($('stockOverview'))$('stockOverview').onclick=()=>show('overview');if($('stockDirectory'))$('stockDirectory').onclick=()=>show('directory');if($('stockInactive'))$('stockInactive').onclick=()=>show('inactive');if($('stockBulk'))$('stockBulk').onclick=()=>show('bulk');}
function summaryGroups(type){const key=type==='warehouse'?'warehouses':type==='client'?'clients':type==='supplier'?'suppliers':type==='r2r'?'r2rOwners':type==='owned'?'ownedPositions':type==='service'?'services':'transit';return Object.values(overviewSummary?.distribution?.[key]||{}).map(x=>({...x,qty:type==='warehouse'?Number(x.availableQty||0):Number(x.qty||0),descriptions:type==='warehouse'?(x.availableDescriptions||{}):(x.descriptions||{})})).filter(x=>x.qty>0).sort((a,b)=>b.qty-a.qty||String(a.name||'').localeCompare(String(b.name||'')));}
function descriptionGroups(group){return Object.entries(group?.descriptions||{}).map(([name,qty])=>({name,qty:Number(qty||0)})).filter(x=>x.qty>0).sort((a,b)=>b.qty-a.qty||a.name.localeCompare(b.name));}
