function donutSvg(groups,total,type){if(!total)return`<div class="h-44 flex items-center justify-center text-xs text-slate-600">No stock</div>`;const r=52,c=2*Math.PI*r;let offset=0;const segs=groups.map((g,n)=>{const len=c*(g.qty/total),dash=`${len} ${Math.max(0,c-len)}`,o=-offset;offset+=len;return`<circle class="stockDonutSlice cursor-pointer" data-type="${type}" data-name="${esc(g.name)}" cx="70" cy="70" r="${r}" fill="none" stroke="${CHART_COLORS[n%CHART_COLORS.length]}" stroke-width="22" stroke-dasharray="${dash}" stroke-dashoffset="${o}" transform="rotate(-90 70 70)"><title>${esc(g.name)}: ${g.qty}</title></circle>`;}).join('');return`<div class="relative w-[180px] h-[180px] mx-auto"><svg viewBox="0 0 140 140" class="w-full h-full"><circle cx="70" cy="70" r="52" fill="none" stroke="#1e293b" stroke-width="22"/>${segs}<circle cx="70" cy="70" r="38" fill="#020617"/></svg><div class="absolute inset-0 flex flex-col items-center justify-center pointer-events-none"><div class="text-2xl sm:text-3xl font-black shrink-0">${total}</div><div class="text-[10px] uppercase text-slate-500">Total Qty</div></div></div>`;}
function legend(groups,type){return`<div class="space-y-1.5 max-h-48 overflow-y-auto pr-1">${groups.map((g,n)=>`<button class="stockDistPick w-full flex items-center gap-2 text-left rounded-lg px-2 py-1.5 hover:bg-slate-800" data-type="${type}" data-name="${esc(g.name)}"><span class="w-2.5 h-2.5 rounded-full shrink-0" style="background:${CHART_COLORS[n%CHART_COLORS.length]}"></span><span class="truncate text-xs flex-1">${esc(g.name)}</span><b class="text-xs">${g.qty}</b></button>`).join('')||'<div class="text-xs text-slate-600">No stock.</div>'}</div>`;}
function distCard(type,title,subtitle){const groups=summaryGroups(type),total=groups.reduce((a,g)=>a+g.qty,0);return`<button class="stockPositionPick bg-slate-900 border ${drill?.type===type?'border-cyan-600':'border-slate-800'} rounded-2xl p-4 min-w-0 text-left hover:border-slate-600" data-type="${type}"><div class="text-[10px] uppercase tracking-wide text-slate-500 break-words">${esc(subtitle)}</div><div class="flex flex-wrap items-end justify-between gap-2 mt-2"><h3 class="font-bold text-base min-w-0 break-words">${esc(title)}</h3><div class="text-3xl font-black min-w-0 break-all tabular-nums">${total}</div></div><div class="text-[10px] text-cyan-400 mt-2">Click to drill down</div></button>`;}
function heroMetric(label,value,sub='',highlight=false){return`<div class="bg-slate-900 border ${highlight?'border-emerald-700/70':'border-slate-800'} rounded-2xl px-3 py-3 sm:p-4 min-w-0"><div class="flex flex-wrap items-start justify-between gap-2 sm:block"><div class="min-w-0"><div class="text-[9px] sm:text-[10px] uppercase tracking-wide ${highlight?'text-emerald-400':'text-slate-500'} break-words">${esc(label)}</div><div class="text-[10px] sm:text-xs text-slate-500 mt-0.5 sm:mt-1 break-words">${esc(sub)}</div></div><div class="text-2xl sm:text-3xl font-black min-w-0 max-w-full break-all tabular-nums sm:mt-1">${Number(value||0)}</div></div></div>`;}
function statusData(){const g=overviewSummary?.global||{};return{'At Supplier':Number(g.atSupplierQty||0),'Available':Number(g.availableQty||0),'Reserved':Number(g.reservedQty||0),'At Client':Number(g.atClientQty||0),'Maintenance':Number(g.maintenanceQty||0),'Inspection':Number(g.inspectionQty||0),'Not Available':Number(g.notAvailableQty||0),'In Transit':Number(g.inTransitQty||0),'Missing':Number(g.missingQty||0),'Stolen':Number(g.stolenQty||0)};}
function statusPanel(){const m=statusData(),total=Number(overviewSummary?.global?.liveQty||0),denom=total||1,ordered=ACTIVE_STATUS.filter(s=>m[s]>0).map(s=>({name:s,qty:m[s]}));return`<section class="bg-slate-900 border border-slate-800 rounded-2xl p-4"><div class="flex flex-wrap justify-between gap-2 mb-3"><div><h3 class="font-bold">Operational Status</h3><div class="text-[10px] text-slate-500">Where live physical stock is in its operating cycle</div></div><b class="text-sm">${total} live qty</b></div><div class="h-4 rounded-full overflow-hidden flex bg-slate-800">${ordered.map((x,n)=>`<div title="${esc(x.name)}: ${x.qty}" style="width:${(x.qty/denom)*100}%;background:${CHART_COLORS[n%CHART_COLORS.length]}"></div>`).join('')}</div><div class="grid sm:grid-cols-2 lg:grid-cols-3 gap-2 mt-4">${ordered.map((x,n)=>`<div class="flex items-center gap-2 text-xs"><span class="w-2.5 h-2.5 rounded-full" style="background:${CHART_COLORS[n%CHART_COLORS.length]}"></span><span class="flex-1 text-slate-400">${esc(x.name)}</span><b>${x.qty}</b><span class="text-slate-600">${Math.round(x.qty/denom*100)}%</span></div>`).join('')||'<div class="text-xs text-slate-600">No live stock.</div>'}</div></section>`;}
function attentionPanel(){const m=statusData(),rows=[['In Transit',m['In Transit']],['Maintenance',m.Maintenance],['Inspection',m.Inspection],['Reserved',m.Reserved],['Not Available',m['Not Available']],['Missing / Stolen',m.Missing+m.Stolen]].filter(x=>x[1]>0);return`<section class="bg-slate-900 border border-slate-800 rounded-2xl p-4"><h3 class="font-bold">Needs Attention</h3><div class="text-[10px] text-slate-500 mb-3">Operational stock worth checking</div><div class="space-y-2">${rows.map(([l,v])=>`<div class="flex items-center justify-between border border-slate-800 rounded-xl px-3 py-2"><span class="text-xs text-slate-400">${esc(l)}</span><b class="text-lg">${v}</b></div>`).join('')||'<div class="text-sm text-emerald-400 border border-emerald-900/50 rounded-xl p-3">No active exception stock.</div>'}</div></section>`;}
