function drillHtml(){if(!drill)return`<section class="bg-slate-900 border border-dashed border-slate-700 rounded-2xl p-5 text-center"><div class="font-semibold">Detailed Stock Position</div><div class="text-xs text-slate-500 mt-1">Click Owned Stock, Warehouse, R2R, Client, Supplier, Service or Transit to see what makes up the total.</div></section>`;const groups=summaryGroups(drill.type),title=drill.type==='r2r'?'R2R':drill.type==='owned'?'Owned Stock':drill.type.charAt(0).toUpperCase()+drill.type.slice(1);if(!drill.name)return`<section class="bg-slate-900 border border-cyan-900/50 rounded-2xl p-4"><div class="flex flex-wrap justify-between gap-2 mb-4"><div><div class="text-[10px] uppercase text-cyan-400">${esc(title)}</div><h3 class="font-bold text-lg">${esc(title)} breakdown</h3><div class="text-xs text-slate-500">Select a location, owner or operational group to see Description totals.</div></div><button id="stockCloseDrill" class="bg-slate-800 px-3 py-2 rounded-lg text-xs">Close</button></div><div class="grid sm:grid-cols-2 xl:grid-cols-3 gap-2">${groups.map(g=>`<button class="stockDrillGroup flex items-center justify-between gap-3 border border-slate-800 rounded-xl px-3 py-3 text-left hover:bg-slate-800" data-type="${esc(drill.type)}" data-name="${esc(g.name)}"><span class="text-sm min-w-0 flex-1 break-words [overflow-wrap:anywhere]">${esc(g.name)}</span><b class="text-lg min-w-0 break-all tabular-nums">${g.qty}</b></button>`).join('')||'<div class="text-xs text-slate-500">No stock in this group.</div>'}</div></section>`;const group=groups.find(x=>x.name===drill.name);if(!group){drill={type:drill.type};return drillHtml();}const descriptions=descriptionGroups(group),total=descriptions.reduce((a,x)=>a+x.qty,0);return`<section class="bg-slate-900 border border-cyan-900/50 rounded-2xl p-4"><div class="flex flex-wrap justify-between gap-2 mb-4"><div class="min-w-0 flex-1"><div class="text-[10px] uppercase text-cyan-400">${esc(title)}</div><h3 class="font-bold text-lg break-words [overflow-wrap:anywhere]">${esc(group.name)}</h3><div class="text-xs text-slate-500">${total} qty · Description breakdown</div></div><div class="flex gap-2"><button id="stockBackDrill" class="bg-slate-800 px-3 py-2 rounded-lg text-xs">Back</button><button id="stockCloseDrill" class="bg-slate-800 px-3 py-2 rounded-lg text-xs">Close</button></div></div><div class="space-y-2 max-h-[420px] overflow-y-auto pr-1">${descriptions.map(x=>`<div class="flex items-start justify-between gap-4 border border-slate-800 rounded-xl px-3 py-3"><span class="text-sm leading-5 min-w-0 flex-1 break-words [overflow-wrap:anywhere]">${esc(x.name)}</span><b class="text-lg min-w-0 max-w-full break-all tabular-nums">${x.qty}</b></div>`).join('')||'<div class="text-xs text-slate-500">No Description detail recorded.</div>'}</div></section>`;}
function summaryUnavailable(){const superadmin=window.IMS_ROLE==='superadmin';$('appContent').innerHTML=`${tabs()}<section class="bg-slate-900 border border-amber-900/60 rounded-2xl p-5"><h2 class="font-bold text-amber-300">Inventory Summary Requires Rebuild</h2><div class="text-sm text-slate-400 mt-2">Owned/R2R quantities are now separated. Rebuild the summary once using current inventory records to activate the accurate drill-down.</div>${superadmin?'<button id="stockRebuildSummary" class="mt-4 bg-emerald-700 px-4 py-2 rounded-lg text-xs font-bold">Rebuild Inventory Summary</button>':'<div class="text-xs text-slate-500 mt-3">A Superadmin must rebuild the inventory summary.</div>'}</section>`;bindTabs();if(superadmin&&$('stockRebuildSummary'))$('stockRebuildSummary').onclick=rebuildSummary;}
async function rebuildSummary(){const btn=$('stockRebuildSummary');if(btn){btn.disabled=true;btn.textContent='Rebuilding...';}try{const email=auth.currentUser?.email||'';const result=await rebuildInventorySummary(email);await addDoc(collection(db,'audit_traces'),{traceVersion:3,actionType:'REBUILD_INVENTORY_SUMMARY',module:'Stock Inventory',targetType:'inventory_summary',targetName:'Inventory Summary',targetId:'inventory_summary',summary:`Rebuild Inventory Summary from ${result.recordCount} inventory records`,beforeValue:null,afterValue:{recordCount:result.recordCount,summaryVersion:SUMMARY_VERSION},changedFields:['inventory_summary'],remark:'',performedBy:email,performedByRole:window.IMS_ROLE||'',performedAt:now()});await loadOverviewSummary();drill=null;renderOverview();}catch(e){alert('Inventory summary rebuild failed: '+(e?.message||e));if(btn){btn.disabled=false;btn.textContent='Rebuild Inventory Summary';}}}
function showStockDrill(){renderOverview();requestAnimationFrame(()=>document.getElementById('stockDrillArea')?.scrollIntoView({block:'nearest',behavior:'smooth'}));}
function bindOverview(){bindTabs();if($('stockOwnedPick'))$('stockOwnedPick').onclick=()=>{drill={type:'owned'};showStockDrill();};document.querySelectorAll('.stockPositionPick').forEach(b=>b.onclick=()=>{drill={type:b.dataset.type};showStockDrill();});document.querySelectorAll('.stockDrillGroup').forEach(b=>b.onclick=()=>{drill={type:b.dataset.type,name:b.dataset.name};showStockDrill();});if($('stockBackDrill'))$('stockBackDrill').onclick=()=>{drill={type:drill?.type};renderOverview();};if($('stockCloseDrill'))$('stockCloseDrill').onclick=()=>{drill=null;renderOverview();};}
