function renderOverview(){if(!overviewSummary)return summaryUnavailable();const g=overviewSummary.global,serviceQty=Number(g.maintenanceQty||0)+Number(g.inspectionQty||0);$('appContent').innerHTML=`${tabs()}<div class="space-y-5 min-w-0 max-w-full"><section class="min-w-0"><div class="mb-3"><h2 class="font-bold text-lg">Stock Balance Snapshot</h2><div class="text-xs text-slate-500">First-sight quantities for quick stock reconciliation. Available is shown last as the practical balance to check.</div></div><div class="grid gap-2 sm:gap-3" style="grid-template-columns:repeat(auto-fit,minmax(min(100%,155px),1fr))"><button type="button" id="stockOwnedPick" class="text-left rounded-2xl focus-visible:ring-2 focus-visible:ring-cyan-400">${heroMetric('Registered Owned',g.registeredOwnedQty,'Click for owned stock distribution')}</button>${heroMetric('R2R Active Stock',g.r2rQty,'Excludes returned / inactive R2R')}${heroMetric('Owned Inactive',Number(g.registeredOwnedQty||0)-Number(g.ownedQty||0),'Included in registered owned')}${heroMetric('Owned at Client',ownedPositionQty('At Client'),'Excludes R2R')}${heroMetric('Owned at Supplier',ownedPositionQty('At Supplier'),'Excludes R2R')}${heroMetric('Owned Service',ownedPositionQty('Service / Inspection'),'Excludes R2R')}${heroMetric('Owned Transit',ownedPositionQty('In Transit'),'Excludes R2R')}${heroMetric('Owned Reserved',ownedPositionQty('Warehouse — Reserved'),'Excludes R2R')}${heroMetric('Owned Available',ownedPositionQty('Warehouse — Available'),'Excludes R2R',true)}</div></section><section class="min-w-0"><div class="mb-3"><h2 class="font-bold text-lg">Detailed Stock Position</h2><div class="text-xs text-slate-500">Owned stock distribution is separate from R2R ownership. Warehouse, Client, Supplier, Service and Transit cards show owned stock only. Click a card to drill down by location/business, then Description.</div></div><div class="grid gap-3" style="grid-template-columns:repeat(auto-fit,minmax(min(100%,190px),1fr))">${distCard('owned','Owned Stock','Live owned stock · all positions')}${distCard('warehouse','Warehouse','Owned available qty')}${distCard('r2r','R2R','Third-party live qty')}${distCard('client','Client','Owned at-client qty')}${distCard('supplier','Supplier','At-supplier qty')}${distCard('service','Service','Maintenance + inspection')}${distCard('transit','Transit','In-transit qty')}</div></section><div id="stockDrillArea">${drillHtml()}</div><div class="text-[10px] text-slate-600 text-right">Summary updated ${esc(g.updatedAt||'—')} · ${Number(g.sourceRecordCount||0)} source record(s) at last rebuild</div></div>`;bindOverview();}

function row(i){return{i,alias:i.alias||'',name:i.name||'',itemCode:i.itemCode||'',type:i.type||'',category:i.category||'',size:i.size||'',grade:i.grade||'',ppf:i.ppf||'',connection:i.connection||'',range:i.range||'',brand:i.brand||'',unit:i.unit||'',supplier:i.supplierName||i.ownerBusinessName||'',ownership:ownership(i),status:status(i),total:qty(i),live:liveQty(i),available:avail(i),distribution:distribution(i),po:i.ourPONumber||''};}
function pageRows(){return directoryItems.map(row);}
function scopedStatuses(){return view==='inactive'?INACTIVE_STATUS:DIRECTORY_STATUS;}
function activeDirectoryConstraints(){const q=[];if(directoryQueryState.searchField&&directoryQueryState.searchValue)q.push([directoryQueryState.searchField,directoryQueryState.searchValue]);for(const [field,value] of Object.entries(directoryQueryState.filters||{}))if(value&&field!=='status')q.push([field,value]);return q;}
function sortedDirectoryConstraints(){const q=[];if(directoryQueryState.searchField&&directoryQueryState.searchValue)q.push([directoryQueryState.searchField,directoryQueryState.searchValue]);for(const field of ['category','status','currentLocation','ownershipType']){const value=directoryQueryState.filters?.[field]||'';if(value)q.push([field,value]);}return q;}
function hasDirectoryQuery(){return Boolean(directoryQueryState.searchValue||Object.values(directoryQueryState.filters||{}).some(Boolean));}
function inventoryBaseQuery(statusOverride='',nameOverride=null){const c=collection(db,'inventory'),parts=[],statusValue=statusOverride||directoryQueryState.filters?.status||'';if(directorySortField){const constraints=sortedDirectoryConstraints(),statusConstraint=constraints.find(x=>x[0]==='status');if(statusConstraint)parts.push(where('status','==',statusConstraint[1]));else parts.push(where('status','in',scopedStatuses()));for(const [field,value] of constraints)if(field!=='status')parts.push(where(field,'==',value));parts.push(orderBy(directorySortField,directorySortDir));return query(c,...parts);}if(statusValue)parts.push(where('status','==',statusValue));else parts.push(where('status','in',scopedStatuses()));for(const [field,value] of activeDirectoryConstraints())parts.push(where(field,'==',field==='name'&&nameOverride!==null?nameOverride:value));return query(c,...parts);}
function inventoryPageQuery(base,cursor){const parts=[];if(cursor)parts.push(startAfter(cursor));parts.push(limit(PAGE_SIZE));return query(base,...parts);}
async function loadDirectory(reset=false){if(directoryLoading)return;directoryLoading=true;if(reset){directoryPage=0;directoryCursors=[null];}if($('stockTable'))$('stockTable').innerHTML='<div class="p-5 text-sm text-slate-500">Loading inventory page...</div>';try{if(directoryQueryState.searchField==='name'&&directoryQueryState.searchValue){directorySortField='';const term=directoryQueryState.searchValue.trim(),normalize=v=>String(v||'').toUpperCase().replace(/[“”]/g,'"').replace(/[’‘]/g,"'").replace(/\s+/g,' ').trim(),words=normalize(term).split(' ').filter(Boolean);let state=directoryCursors[0];if(!state?.descriptionSearch){const summary=await getDoc(SUMMARY_DISTRIBUTION);if(!summary.exists()||summary.data().summaryVersion!==SUMMARY_VERSION)throw Error('Inventory summary unavailable. Rebuild the summary before keyword searching.');const d=summary.data(),names=new Set([term,term.toUpperCase(),term.toLowerCase()]);for(const group of [...Object.values(d.ownedPositions||{}),...Object.values(d.r2rOwners||{})])for(const name of Object.keys(group.descriptions||{}))if(words.every(w=>normalize(name).includes(w)))names.add(name);const statuses=directoryQueryState.filters?.status?[directoryQueryState.filters.status]:scopedStatuses(),segments=[];for(const name of [...names].sort((a,b)=>a.localeCompare(b)))for(const status of statuses)segments.push({name,status});const populated=[];for(let n=0;n<segments.length;n+=20){const batch=segments.slice(n,n+20),counts=await Promise.all(batch.map(x=>getCountFromServer(inventoryBaseQuery(x.status,x.name))));batch.forEach((x,i)=>{const count=counts[i].data().count||0;if(count)populated.push({...x,count});});}state={descriptionSearch:true,segments:populated,index:0,last:null};directoryCursors=[state];}const saved=directoryCursors[directoryPage]||state,segments=state.segments;directoryTotal=segments.reduce((n,x)=>n+x.count,0);let index=saved.index,last=saved.last,docs=[];while(index<segments.length&&docs.length<PAGE_SIZE){const seg=segments[index],take=PAGE_SIZE-docs.length,parts=[];if(last)parts.push(startAfter(last));parts.push(limit(take));const part=await getDocs(query(inventoryBaseQuery(seg.status,seg.name),...parts));docs.push(...part.docs);if(part.size<take){index++;last=null;}else last=part.docs.at(-1);}directoryItems=docs.map(d=>({id:d.id,...d.data()}));directoryCursors[directoryPage+1]={descriptionSearch:true,index,last};if(reset)renderDirectory();renderTable();return;}let snap=null,countSnap=null;const base=inventoryBaseQuery(),cursor=directoryCursors[directoryPage];if(!cursor?.segmented){try{[snap,countSnap]=await Promise.all([getDocs(inventoryPageQuery(base,cursor)),getCountFromServer(base)]);}catch(e){if(e?.code!=='failed-precondition'||!/index/i.test(e.message||''))throw e;if(directorySortField){directorySortField='';directoryPage=0;directoryCursors=[null];reset=true;try{const unsorted=inventoryBaseQuery();[snap,countSnap]=await Promise.all([getDocs(inventoryPageQuery(unsorted,null)),getCountFromServer(unsorted)]);}catch(second){if(second?.code!=='failed-precondition'||!/index/i.test(second.message||''))throw second;}}}}if(snap&&countSnap){directoryItems=snap.docs.map(d=>({id:d.id,...d.data()}));directoryTotal=countSnap.data().count||0;if(snap.docs.length)directoryCursors[directoryPage+1]=snap.docs.at(-1);}else{directorySortField='';const selected=directoryQueryState.filters?.status||'',statuses=selected?[selected]:scopedStatuses(),saved=directoryCursors[directoryPage];if(directoryPage>0&&!saved?.segmented){directoryPage=0;directoryCursors=[null];reset=true;}const counts=await Promise.all(statuses.map(status=>getCountFromServer(inventoryBaseQuery(status))));directoryTotal=counts.reduce((n,c)=>n+(c.data().count||0),0);let index=saved?.segmented?saved.index:0,last=saved?.segmented?saved.last:null;const docs=[];while(index<statuses.length&&docs.length<PAGE_SIZE){if(!last&&!counts[index].data().count){index++;continue;}const take=PAGE_SIZE-docs.length,parts=[];if(last)parts.push(startAfter(last));parts.push(limit(take));const part=await getDocs(query(inventoryBaseQuery(statuses[index]),...parts));docs.push(...part.docs);if(part.size<take){index++;last=null;}else last=part.docs.at(-1);}directoryItems=docs.map(d=>({id:d.id,...d.data()}));directoryCursors[directoryPage+1]={segmented:true,index,last};}if(reset)renderDirectory();renderTable();}catch(e){console.error('IMS inventory server query failed:',e);directoryItems=[];directoryTotal=0;if($('stockTable'))$('stockTable').innerHTML='<div class="p-5 text-sm text-amber-300 break-words">Inventory query unavailable: '+esc(/index/i.test(e?.message||'')?'This filter combination requires a Firestore index. Try fewer filters or contact the administrator.':e?.message||e)+'</div>';}finally{directoryLoading=false;}}
function activateDirectorySearch(activeId,field){for(const id of ['stockAliasFilter','stockNameFilter'])if(id!==activeId&&$(id))$(id).value='';directoryQueryState.searchField=$(activeId)?.value.trim()?field:'';directoryQueryState.searchValue=$(activeId)?.value.trim()||'';}
function collectDirectoryState(){const alias=$('stockAliasFilter')?.value.trim()||'',name=$('stockNameFilter')?.value.trim()||'';directoryQueryState.searchField=alias?'alias':name?'name':'';directoryQueryState.searchValue=alias||name||'';directoryQueryState.filters={category:$('stockCategoryFilter')?.value||'',size:$('stockSizeFilter')?.value||'',status:$('stockStatusFilter')?.value||'',currentLocation:$('stockLocationFilter')?.value||'',ownershipType:$('stockOwnershipFilter')?.value||''};}
async function applyDirectoryFilter(){collectDirectoryState();directorySortField='';await loadDirectory(true);}
async function clearDirectoryQuery(){directorySortField='';directoryQueryState={searchField:'',searchValue:'',filters:{category:'',size:'',status:'',currentLocation:'',ownershipType:''}};for(const id of ['stockAliasFilter','stockNameFilter','stockCategoryFilter','stockSizeFilter','stockStatusFilter','stockLocationFilter','stockOwnershipFilter'])if($(id))$(id).value='';await loadDirectory(true);}
function categoryOptions(){return Object.keys(overviewSummary?.categories?.categories||{}).sort((a,b)=>a.localeCompare(b));}
function locationOptions(){const d=overviewSummary?.distribution||{},names=[];for(const key of ['warehouses','clients','suppliers'])for(const x of Object.values(d[key]||{}))if(x?.name)names.push(x.name);return[...new Set(names)].sort((a,b)=>a.localeCompare(b));}
function optionList(values,current,label){return`<option value="">All ${esc(label)}</option>${values.map(v=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(v)}</option>`).join('')}`;}
function filterSummary(){const parts=[];if(directoryQueryState.searchField)parts.push(`${directoryQueryState.searchField} = ${directoryQueryState.searchValue}`);for(const[f,v]of Object.entries(directoryQueryState.filters||{}))if(v)parts.push(`${f} = ${v}`);return parts;}
function masterActive(x){return x?.status!=='inactive';}
function masterPartyName(x){return x?.companyName||x?.clientName||x?.supplierName||'';}
function uniqMaster(values){return[...new Set(values.map(v=>String(v||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,undefined,{numeric:true,sensitivity:'base'}));}
async function loadDirectoryMasters(){if(masterLoading)return masterLoading;masterLoading=(async()=>{const[settingsSnap,clientsSnap,suppliersSnap]=await Promise.all([getDocs(collection(db,'settings')),getDocs(collection(db,'client_profiles')),getDocs(collection(db,'supplier_profiles'))]),settings=settingsSnap.docs.map(d=>({id:d.id,...d.data()})).filter(masterActive),clients=clientsSnap.docs.map(d=>({id:d.id,...d.data()})).filter(masterActive),suppliers=suppliersSnap.docs.map(d=>({id:d.id,...d.data()})).filter(masterActive);masterCategories=uniqMaster(settings.filter(x=>x.type==='category').map(x=>x.value));masterSizes=uniqMaster(settings.filter(x=>x.type==='size').map(x=>x.value));masterLocations=uniqMaster([...settings.filter(x=>x.type==='warehouse').map(x=>x.value),...clients.map(masterPartyName),...suppliers.map(masterPartyName)]);return{masterCategories,masterSizes,masterLocations};})().catch(error=>{masterLoading=null;throw error;});return masterLoading;}
function refillMaster(select,values,label){if(!select)return;const current=select.value;select.innerHTML=`<option value="">All ${label}</option>${values.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('')}`;if([...select.options].some(o=>o.value===current))select.value=current;}
async function hydrateDirectoryMasters(){const category=$('stockCategoryFilter'),size=$('stockSizeFilter'),location=$('stockLocationFilter');if(!category&&!size&&!location)return;try{await loadDirectoryMasters();refillMaster(category,masterCategories,'Categories');refillMaster(size,masterSizes,'Sizes');refillMaster(location,masterLocations,'Locations');}catch(error){console.error('IMS inventory filter master load failed:',error);}}
function sortFieldForLabel(label){return SORT_FIELDS.find(([name])=>name===label)?.[1]||'';}
async function changeDirectorySort(field){if(!field)return;if(directoryLoading)return;if(directoryQueryState.searchField==='name'&&directoryQueryState.searchValue)return alert('Description keyword results are grouped by stored description and status. Clear the search to use column sorting.');directorySortDir=directorySortField===field?(directorySortDir==='asc'?'desc':'asc'):'asc';directorySortField=field;await loadDirectory(true);}

async function editAlias(id){if(!can('inventory.alias.edit'))return;const i=directoryItems.find(x=>x.id===id);if(!i)return;const entered=prompt('Edit Wellora SN',i.alias||'');if(entered===null)return;const alias=entered.trim().replace(/\s+/g,' ');if(alias===i.alias)return;const reason=prompt('Reason for changing Wellora SN (required)','');if(!reason?.trim())return;const dup=alias?await getDocs(query(collection(db,'inventory'),where('alias','==',alias),limit(2))):null;if(dup&&dup.docs.some(d=>d.id!==id))return alert('Wellora SN already exists.');const email=auth.currentUser?.email||'',at=now();await updateDoc(doc(db,'inventory',id),{alias,lastEditedAt:at,lastEditedBy:email});await addDoc(collection(db,'audit_traces'),{traceVersion:3,actionType:'UPDATE_ITEM_ALIAS',module:'Stock Inventory',targetType:'inventory',targetName:alias||i.itemCode,targetId:id,summary:`Update Wellora SN: ${alias}`,beforeValue:{alias:i.alias||''},afterValue:{alias},changedFields:['alias'],remark:reason.trim(),performedBy:email,performedByRole:window.IMS_ROLE||'',performedAt:at});await loadDirectory(false);}

