 const fields=[['weight','Weight','',''],['weightUnit','Weight Unit','weight_unit','weightUnitId'],['name','Description','',''],['category','Category','category','categoryId'],['size','Size','size','sizeId'],['grade','Grade','grade','gradeId'],['ppf','PPF','ppf','ppfId'],['connection','Connection','connection','connectionId'],['range','Range','range','rangeId'],['brand','Brand','brand','brandId']];
